package ch.jalu.configme.configurationdata;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Collections;
import java.util.Arrays;

public class CommentsConfigurationTest {

    @Test
    public void newCommentConfiguration_emptyComments() {
        CommentsConfiguration config = new CommentsConfiguration();
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(Collections.emptyMap(), comments);
    }

    @Test
    public void newCommentConfiguration_singleComment() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "test";
        List<String> commentLines = Arrays.asList("comment");
        config.setComment(path, commentLines.get(0));
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(Collections.singletonMap(path, Collections.singletonList(commentLines.get(0))), comments);
    }

    @Test
    public void newCommentConfiguration_multipleComments() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "test";
        List<String> commentLines = Arrays.asList("comment1", "comment2");
        config.setComment(path, commentLines.get(0), commentLines.get(1));
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(Collections.singletonMap(path, Collections.singletonList(commentLines)), comments);
    }

    @Test
    public void newCommentConfiguration_setMultipleTimes() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "test";
        List<String> commentLines1 = Arrays.asList("comment1");
        List<String> commentLines2 = Arrays.asList("comment2", "");
        config.setComment(path, commentLines1.get(0), commentLines2.get(0));
        config.setComment(path, commentLines2.get(1));
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(Collections.singletonMap(path, Collections.singletonList(commentLines2)), comments);
    }

    @Test
    public void existingCommentConfiguration_setNewLines() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "test";
        List<String> commentLines = Arrays.asList("comment");
        config.setComment(path, commentLines.get(0));
        List<String> newLines = Arrays.asList("new1", "new2");
        config.setComment(path, newLines);
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(Collections.singletonMap(path, Collections.singletonList(newLines)), comments);
    }

    @Test
    public void existingCommentConfiguration_setExistingNewLine() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "test";
        List<String> commentLines = Arrays.asList("comment");
        config.setComment(path, commentLines.get(0));
        String newLine = "new1";
        config.setComment(path, newLine);
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(Collections.singletonMap(path, Collections.singletonList(commentLines)), comments);
    }

    @Test
    public void getAllComments_returnEmptyMapWhenCreatedWithoutArguments() {
        CommentsConfiguration config = new CommentsConfiguration();
        Map<String, List<String>> comments = config.getAllComments();
        assertTrue(comments.isEmpty());
    }
}
